import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"51、【震】 震下震上","description":"横渠易说 - 51、【震】 震下震上","frontmatter":{"title":"51、【震】 震下震上","description":"横渠易说 - 51、【震】 震下震上"},"headers":[],"relativePath":"zh/classics/hengqu/053.md","filePath":"zh/classics/hengqu/053.md"}'),l={name:"zh/classics/hengqu/053.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_51、【震】-震下震上" tabindex="-1">51、【震】 震下震上 <a class="header-anchor" href="#_51、【震】-震下震上" aria-label="Permalink to “51、【震】 震下震上”">​</a></h1><h3 id="彖曰-震亨-震来虩虩-恐致福也-笑言哑哑-后有则也。-震惊百里-惊远而惧迩也-出可以守宗庙社稷以为祭主也。" tabindex="-1">彖曰：“震亨，震来虩虩”，恐致福也；“笑言哑哑”，后有则也。“震惊百里”，惊远而惧迩也，出可以守宗庙社稷以为祭主也。 <a class="header-anchor" href="#彖曰-震亨-震来虩虩-恐致福也-笑言哑哑-后有则也。-震惊百里-惊远而惧迩也-出可以守宗庙社稷以为祭主也。" aria-label="Permalink to “彖曰：“震亨，震来虩虩”，恐致福也；“笑言哑哑”，后有则也。“震惊百里”，惊远而惧迩也，出可以守宗庙社稷以为祭主也。”">​</a></h3><h3 id="象曰-洊雷震-君子以恐惧修省。" tabindex="-1">象曰：洊雷震，君子以恐惧修省。 <a class="header-anchor" href="#象曰-洊雷震-君子以恐惧修省。" aria-label="Permalink to “象曰：洊雷震，君子以恐惧修省。”">​</a></h3><p>此卦纯以君出子在而言，则震之体全而用显，故曰“出可以守宗庙社稷”，不杂言君父共国之时也。</p><h3 id="初九-震来虩虩-后笑言哑哑-吉。-象曰-震来虩虩-恐致福也-笑言哑哑-后有则也。" tabindex="-1">初九，震来虩虩，后笑言哑哑，吉。 象曰：“震来虩虩”，恐致福也；“笑言哑哑”，后有则也。 <a class="header-anchor" href="#初九-震来虩虩-后笑言哑哑-吉。-象曰-震来虩虩-恐致福也-笑言哑哑-后有则也。" aria-label="Permalink to “初九，震来虩虩，后笑言哑哑，吉。 象曰：“震来虩虩”，恐致福也；“笑言哑哑”，后有则也。”">​</a></h3><h3 id="六二-震来厉-亿丧贝-跻于九陵-勿逐-七日得。-象曰-震来厉-乘刚也。" tabindex="-1">六二，震来厉，亿丧贝，跻于九陵，勿逐，七日得。 象曰：“震来厉”，乘刚也。 <a class="header-anchor" href="#六二-震来厉-亿丧贝-跻于九陵-勿逐-七日得。-象曰-震来厉-乘刚也。" aria-label="Permalink to “六二，震来厉，亿丧贝，跻于九陵，勿逐，七日得。 象曰：“震来厉”，乘刚也。”">​</a></h3><p>初动而之上，故曰“跻于九陵”。亿，必也。</p><h3 id="六三-震苏苏-震行无眚。-象曰-震苏苏-位不当也。" tabindex="-1">六三，震苏苏，震行无眚。 象曰：“震苏苏”，位不当也。 <a class="header-anchor" href="#六三-震苏苏-震行无眚。-象曰-震苏苏-位不当也。" aria-label="Permalink to “六三，震苏苏，震行无眚。 象曰：“震苏苏”，位不当也。”">​</a></h3><p>苏苏亦索索之义，处非其地，故危困不一，能惧而改行，则无眚矣。</p><h3 id="九四-震遂泥。-象曰-震遂泥-未光也。" tabindex="-1">九四，震遂泥。 象曰：“震遂泥”，未光也。 <a class="header-anchor" href="#九四-震遂泥。-象曰-震遂泥-未光也。" aria-label="Permalink to “九四，震遂泥。 象曰：“震遂泥”，未光也。”">​</a></h3><p>处众阴之中，为众附比，刚阳之德而以位阴，故泥而未光也。</p><h3 id="六五-震往来厉-亿无丧有事。-象曰-震往来厉-危行也-其事在中-大无丧也。" tabindex="-1">六五，震往来厉，亿无丧有事。 象曰：“震往来厉”，危行也，其事在中，大无丧也。 <a class="header-anchor" href="#六五-震往来厉-亿无丧有事。-象曰-震往来厉-危行也-其事在中-大无丧也。" aria-label="Permalink to “六五，震往来厉，亿无丧有事。 象曰：“震往来厉”，危行也，其事在中，大无丧也。”">​</a></h3><p>惧往亦厉，惧来亦厉，能行己以危，则富贵可保，故曰“无丧有事”，犹云不失其所有也。以其乘刚故危，以其在中故无丧，祸至与不至皆惧，则无丧有事。一有云惧阴之中。</p><h3 id="上六-震索索-视矍矍-征凶。震不于其躬-于其邻-无咎。婚媾有言。-象曰-震索索-中未得也。虽凶无咎-畏邻戒也。" tabindex="-1">上六，震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。 象曰：“震索索”，中未得也。虽凶无咎，畏邻戒也。 <a class="header-anchor" href="#上六-震索索-视矍矍-征凶。震不于其躬-于其邻-无咎。婚媾有言。-象曰-震索索-中未得也。虽凶无咎-畏邻戒也。" aria-label="Permalink to “上六，震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。 象曰：“震索索”，中未得也。虽凶无咎，畏邻戒也。”">​</a></h3><p>危以动，惧以语，无交而求，则民弗与也，故以征则凶，能以邻为惧，则可免咎。邻谓五也，五既附四，己或与焉，则招悔而有言矣，能以邻为戒，不待及身而戒则无咎。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
